return [{
  source_system: "website",
  source_event_id: "demo_new_enquiry_001",
  contact: {
    first_name: "Demo",
    last_name: "Lead",
    email: "user@example.com",
    phone: "+1234567890",
    company: "Example Property Group"
  },
  enquiry: {
    message: "Please contact me about a property enquiry.",
    service: "property_enquiry"
  }
}];

// One enquiry per execution. Reject containers/types rather than stringify them.
const received_at = new Date().toISOString();
const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const raw = Object.prototype.hasOwnProperty.call($json, 'body') ? $json.body : $json;
const errors = [];
if (!isObject(raw)) errors.push('payload must be a JSON object');
const input = isObject(raw) ? raw : {};
for (const key of ['contact','enquiry']) if (input[key] !== undefined && !isObject(input[key])) errors.push(key + ' must be an object');
const clean = (value, field, max = 500) => {
  if (value === undefined || value === null) return undefined;
  if (typeof value !== 'string') { errors.push(field + ' must be a string'); return undefined; }
  const text = value.trim();
  if (!text || /^(null|undefined|n\/a)$/i.test(text)) return undefined;
  if (text.length > max) errors.push(field + ' exceeds ' + max + ' characters');
  return text;
};
const contact = isObject(input.contact) ? input.contact : {};
const enquiry = isObject(input.enquiry) ? input.enquiry : {};
const phone = clean(contact.phone,'contact.phone',40);
const source_system = clean(input.source_system,'source_system',40)?.toLowerCase();
const source_event_id = clean(input.source_event_id,'source_event_id',200);
const data = {source_system,source_event_id,received_at,
  source_received_at:clean(input.received_at,'received_at',40),
  correlation_id:source_system && source_event_id ? source_system + ':' + source_event_id : undefined,
  contact:{first_name:clean(contact.first_name,'contact.first_name',100),last_name:clean(contact.last_name,'contact.last_name',100),
    email:clean(contact.email,'contact.email',254)?.toLowerCase(),
    phone:phone?.replace(/[\s().-]/g,'').replace(/^00/,'+'),company:clean(contact.company,'contact.company',200)},
  enquiry:{message:clean(enquiry.message,'enquiry.message',10000),service:clean(enquiry.service,'enquiry.service',100)?.toLowerCase()},
  validation_errors:errors};
return [{json:data}];

const data = $json;
const errors = [...data.validation_errors];
if (!data.source_system || !/^[a-z0-9_-]+$/.test(data.source_system)) errors.push('source_system must contain only letters, digits, underscores or hyphens');
if (!data.source_event_id || /[\x00-\x1f\x7f]/.test(data.source_event_id)) errors.push('source_event_id is required and must not contain control characters');
if (data.contact.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.contact.email)) errors.push('contact.email is invalid');
if (data.contact.phone && !/^\+[1-9]\d{7,14}$/.test(data.contact.phone)) errors.push('contact.phone must include a country code, e.g. +1234567890');
if (!data.contact.email && !data.contact.phone) errors.push('contact.email or a usable contact.phone is required');
if (!data.enquiry.message && !data.enquiry.service) errors.push('enquiry.message or enquiry.service is required');
data.validation_errors = errors;
data.is_valid = errors.length === 0;
if (!data.is_valid) Object.assign(data,{result:'rejected',http_status:400,reason:errors.join('; '),retryable:false});
if (data.is_valid) {
  try {
    const config = $('Configure HubSpot').first().json;
    data.config = {
      pipeline_id: String(config.hubspot_pipeline_id || '').trim(),
      stage_id: String(config.hubspot_stage_id || '').trim(),
      owner_id: String(config.hubspot_owner_id || '').trim(),
      event_key_property: String(config.hubspot_event_key_property || '').trim()
    };
    const missing = Object.entries(data.config).filter(([,value])=>!value || /^YOUR_[A-Z0-9_]+$/.test(value)).map(([key])=>key);
    if (!/^[a-z][a-z0-9_]*$/.test(data.config.event_key_property)) missing.push('valid event_key_property');
    if (missing.length) throw new Error('Missing or invalid configuration: ' + missing.join(', '));
    const dealProperties = [
      'source_event_id',
      data.config.event_key_property,
      'pipeline',
      'dealstage',
      'hubspot_owner_id',
      'lead_received_at',
      'first_human_response_at',
      'delivery_status',
      'lead_response_sla_status'
    ].filter((value,index,list)=>list.indexOf(value)===index).join(',');
    const dealLookupBase = 'https://api.hubapi.com/crm/v3/objects/deals/' +
      encodeURIComponent(data.correlation_id) +
      '?idProperty=' + encodeURIComponent(data.config.event_key_property);
    data.duplicate_lookup_body = {
      filterGroups: [{filters: [{propertyName:data.config.event_key_property,operator:'EQ',value:data.correlation_id}]}],
      properties: [data.config.event_key_property],
      limit: 2
    };
    data.deal_verification_url = dealLookupBase +
      '&properties=' + encodeURIComponent(dealProperties) +
      '&associations=contacts';
    data.contact_lookup_body = {
      filterGroups: [{filters: [{propertyName:data.contact.email?'email':'phone',operator:'EQ',value:data.contact.email||data.contact.phone}]}],
      properties: ['firstname','lastname','email','phone','company'],
      limit: 2
    };
  } catch (error) {
    data.is_valid = false;
    Object.assign(data,{result:'configuration_error',http_status:500,reason:'Configure the required non-secret HubSpot settings in Configure HubSpot.',retryable:false});
  }
}
return [{json:data}];

const data = {...$('Validate Inbound Enquiry').first().json};
const status = Number($json.statusCode) || 0;
const parseJson = body => {
  if (body === undefined || body === null || body === '') return null;
  if (typeof body === 'object') return body;
  if (typeof body !== 'string') return null;
  try { return JSON.parse(body); } catch { return null; }
};
const failure = (reason, httpStatus = 502) => ({...data,result:'hubspot_failure',step:'Check Existing Event',reason,http_status:httpStatus,delivery_status:'FAILED',retryable:httpStatus===503,upstream_status:status||null});
if (status !== 200) {
  return [{json:failure('Event search failed; no records were created.',status === 429 || status >= 500 || !status ? 503 : 502)}];
}
const response = parseJson($json.body ?? $json.data);
const total = Number(response?.total);
const results = response?.results;
if (!Number.isInteger(total) || total < 0 || !Array.isArray(results)) {
  return [{json:failure('HubSpot returned an unreadable Deal search response.')}];
}
if (total === 0 && results.length === 0) {
  data.event_is_new = true;
  return [{json:data}];
}
if (total === 1 && results.length === 1 && results[0]?.id) {
  Object.assign(data,{event_is_new:false,result:'duplicate_event_no_op',http_status:200,deal_id:results[0].id,retryable:false});
  return [{json:data}];
}
if (total > 1 || results.length > 1) {
  return [{json:{...data,event_is_new:false,result:'manual_review_required',http_status:409,delivery_status:'UNKNOWN',reason:'Multiple Deals match source_event_key. Resolve the data integrity issue before replaying.',retryable:false}}];
}
return [{json:failure('Deal search response was internally inconsistent; no records were created.')}];

const data = {...$('Validate Inbound Enquiry').first().json};
const status = Number($json.statusCode) || 0;
const parseJson = body => {
  if (body === undefined || body === null || body === '') return null;
  if (typeof body === 'object') return body;
  if (typeof body !== 'string') return null;
  try { return JSON.parse(body); } catch { return null; }
};
const failure = (reason, httpStatus = 502) => ({...data,result:'hubspot_failure',step:'Find Contact',reason,http_status:httpStatus,delivery_status:'FAILED',retryable:httpStatus===503,upstream_status:status||null});
if (status === 404) {
  Object.assign(data,{can_deliver:true,contact_exists:false,contact_id:undefined});
  return [{json:data}];
}
if (status !== 200) return [{json:failure('Contact lookup failed.',status === 429 || status >= 500 || !status ? 503 : 502)}];
const response = parseJson($json.body ?? $json.data);
if (!response) return [{json:failure('HubSpot returned an unreadable Contact lookup response.')}];
const matches = Array.isArray(response.results) ? response.results : null;
if (!matches) return [{json:failure('HubSpot returned an invalid Contact search response.')}];
if (matches.length > 1 || Number(response.total) > 1) {
  const identity = data.contact.email ? 'email' : 'normalized phone';
  return [{json:{...data,result:'manual_review_required',http_status:409,delivery_status:'FAILED',reason:'Multiple Contacts match this '+identity+'. Select the correct Contact manually.',retryable:false}}];
}
Object.assign(data,{can_deliver:true,contact_exists:matches.length===1,contact_id:matches[0]?.id});
return [{json:data}];

const data = {...$('Classify Contact Search Result').first().json};
const status = Number($json.statusCode) || 0;
const parseJson = body => {
  if (body === undefined || body === null || body === '') return null;
  if (typeof body === 'object') return body;
  if (typeof body !== 'string') return null;
  try { return JSON.parse(body); } catch { return null; }
};
const response = status >= 200 && status < 300 ? parseJson($json.body ?? $json.data) : null;
const confirmed = Boolean(response?.id);
Object.assign(data,{contact_created:confirmed,contact_id:confirmed?response.id:undefined,contact_create_status:status||null});
return [{json:data}];

const data = {...$('Capture Created Contact').first().json};
const status = Number($json.statusCode) || 0;
const parseJson = body => {
  if (body === undefined || body === null || body === '') return null;
  if (typeof body === 'object') return body;
  if (typeof body !== 'string') return null;
  try { return JSON.parse(body); } catch { return null; }
};
const failure = (step, reason, httpStatus = 502, uncertain = false) => ({...data,result:'hubspot_failure',step,reason,http_status:httpStatus,delivery_status:uncertain?'UNKNOWN':'FAILED',retryable:uncertain||httpStatus===503,upstream_status:status||null});
let matches;
if (status === 404) matches = [];
else if (status === 200) {
  const response = parseJson($json.body ?? $json.data);
  if (!response) return [{json:failure('Recover Contact','HubSpot returned an unreadable Contact recovery response.')}];
  matches = Array.isArray(response.results) ? response.results : null;
  if (matches && Number(response.total) > 1) {
    const identity = data.contact.email ? 'email' : 'normalized phone';
    return [{json:{...data,result:'manual_review_required',http_status:409,delivery_status:'UNKNOWN',reason:'Multiple Contacts match this '+identity+' during recovery. Select the correct Contact manually; do not create another Contact.',retryable:false}}];
  }
} else {
  const definitiveCreateFailure = [400,401,403,422].includes(Number(data.contact_create_status));
  return [{json:failure('Recover Contact',definitiveCreateFailure?'HubSpot rejected Contact creation; correct the configuration or payload before replaying.':'Contact recovery lookup failed; do not retry the Contact POST blindly.',definitiveCreateFailure?502:503,!definitiveCreateFailure)}];
}
if (!matches) return [{json:failure('Recover Contact','HubSpot returned an invalid phone recovery response.')}];
if (matches.length > 1) {
  const identity = data.contact.email ? 'email' : 'normalized phone';
  return [{json:{...data,result:'manual_review_required',http_status:409,delivery_status:'UNKNOWN',reason:'Multiple Contacts match this '+identity+' during recovery. Select the correct Contact manually; do not create another Contact.',retryable:false}}];
}
if (matches.length === 1) {
  Object.assign(data,{contact_id:matches[0].id,contact_created:false,contact_recovered:true});
  return [{json:data}];
}
const definitiveCreateFailure = [400,401,403,422].includes(Number(data.contact_create_status));
const identity = data.contact.email ? 'email' : 'normalized phone';
return [{json:failure('Create Contact',definitiveCreateFailure?'HubSpot rejected Contact creation. Correct the configuration or payload before replaying.':'Contact creation could not be confirmed and no Contact was found by '+identity+'. Check HubSpot before intervention; do not retry the Contact POST blindly.',definitiveCreateFailure?502:503,!definitiveCreateFailure)}];

const data = $json;

data.deal_properties = {
  dealname:
    (
      [data.contact.first_name, data.contact.last_name]
        .filter(Boolean)
        .join(' ') ||
      data.contact.email ||
      data.contact.phone
    ) +
    ' - ' +
    data.source_system +
    ' Enquiry',

  pipeline: data.config.pipeline_id,
  dealstage: data.config.stage_id,
  hubspot_owner_id: data.config.owner_id,

  description: [
    data.enquiry.service,
    data.enquiry.message
  ].filter(Boolean).join(' — '),

  lead_received_at: data.received_at,
  lead_response_sla_status: 'AWAITING_RESPONSE',
  delivery_status: 'DELIVERED',

  // Raw event ID provided by the source system
  source_event_id: data.source_event_id
};

// Globally unique idempotency key, e.g. website:12345
data.deal_properties[data.config.event_key_property] =
  data.correlation_id;

return [{ json: data }];

const data = {...$('Prepare HubSpot Deal').first().json};
const status = Number($json.statusCode) || 0;
const parseJson = body => {
  if (body === undefined || body === null || body === '') return null;
  if (typeof body === 'object') return body;
  if (typeof body !== 'string') return null;
  try { return JSON.parse(body); } catch { return null; }
};
const response = status >= 200 && status < 300 ? parseJson($json.body ?? $json.data) : null;
Object.assign(data,{deal_write_status:status||null,deal_write_confirmed:Boolean(response?.id),created_deal_id:response?.id});
return [{json:data}];

const data = {...$('Capture Deal Write Outcome').first().json};
const status = Number($json.statusCode) || 0;
const parseJson = body => {
  if (body === undefined || body === null || body === '') return null;
  if (typeof body === 'object') return body;
  if (typeof body !== 'string') return null;
  try { return JSON.parse(body); } catch { return null; }
};
const failure = (reason, httpStatus = 503, uncertain = true) => ({...data,result:'hubspot_failure',step:'Create Deal',reason,http_status:httpStatus,delivery_status:uncertain?'UNKNOWN':'FAILED',retryable:uncertain||httpStatus===503,upstream_status:status||null});
if (status === 200) {
  const deal = parseJson($json.body ?? $json.data);
  const properties = deal?.properties || {};
  const contacts = deal?.associations?.contacts?.results || [];
  const associated = contacts.some(contact=>String(contact.id)===String(data.contact_id));
  const verified = Boolean(deal?.id) &&
    properties.source_event_id === data.source_event_id &&
    properties[data.config.event_key_property] === data.correlation_id &&
    properties.pipeline === data.config.pipeline_id &&
    properties.dealstage === data.config.stage_id &&
    String(properties.hubspot_owner_id) === data.config.owner_id &&
    properties.delivery_status === 'DELIVERED' &&
    properties.lead_response_sla_status === 'AWAITING_RESPONSE' &&
    !properties.first_human_response_at &&
    Boolean(properties.lead_received_at) &&
    associated;
  if (!verified) {
    return [{json:{...data,result:'manual_review_required',http_status:409,deal_id:deal?.id,delivery_status:'UNKNOWN',reason:'Deal exists but its identity, SLA state, owner, pipeline, stage, receipt time or Contact association did not verify. Inspect it; do not create another Deal.',retryable:false}}];
  }
  Object.assign(data,{result:'enquiry_delivered',http_status:200,deal_id:deal.id,lead_received_at:properties.lead_received_at,delivery_status:properties.delivery_status,lead_response_sla_status:properties.lead_response_sla_status,recovered_after_write_error:!data.deal_write_confirmed,retryable:false});
  return [{json:data}];
}
const definitiveWriteFailure = [400,401,403,422].includes(Number(data.deal_write_status));
return [{json:failure(definitiveWriteFailure?'HubSpot rejected Deal creation. Correct the configuration or payload before replaying.':'Deal delivery could not be confirmed. Replay the SAME source event ID; never generate a new ID for this retry.',definitiveWriteFailure?502:503,!definitiveWriteFailure)}];

const data = $json;
const allowed = ['result','reason','step','source_event_id','correlation_id','contact_id','deal_id','lead_received_at','delivery_status','lead_response_sla_status','retryable','upstream_status','recovered_after_write_error'];
const body = Object.fromEntries(allowed.filter(key=>data[key] !== undefined).map(key=>[key,data[key]]));
if (!body.result) throw new Error('Workflow reached Return Result without an outcome');
return [{json:{...body,http_status:data.http_status || 500,execution_id:String($execution.id)}}];
